WITH flattened_attrs AS (SELECT id, status_code, payload_json, context, SIZE(context) AS num_context, context['version'] AS version FROM app_logs) SELECT CASE WHEN status_code >= 403 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, AVG(status_code) AS avg_status_code, COUNT(*) AS cnt, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(status_code, 0.95) AS status_code_p95 FROM flattened_attrs GROUP BY CASE WHEN status_code >= 403 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY cnt DESC;
